<script setup lang="ts">
import { computed, onMounted, ref, watch } from "vue";
import { Building2, CreditCard, GraduationCap, Users } from "lucide-vue-next";
import { useRoute } from "vue-router";
import DataPanel from "@/components/operations/DataPanel.vue";
import MetricCard from "@/components/operations/MetricCard.vue";
import StatusBadge from "@/components/operations/StatusBadge.vue";
import { currentUser } from "@/lib/api";
import { operationsRepository } from "@/data/repositories/operationsRepository";
import type { UiInstituteRecord, UiMemberRecord, UiStudentRecord, UiSubscriptionRecord } from "@/data/models/operations";

const route = useRoute(); const loading = ref(true); const error = ref(""); const institute = ref<UiInstituteRecord | null>(null); const members = ref<UiMemberRecord[]>([]); const students = ref<UiStudentRecord[]>([]); const subscriptions = ref<UiSubscriptionRecord[]>([]);
const instituteId = () => Number(route.params.instituteId);
const canViewBilling = computed(() => currentUser()?.roles?.some((role) => ["system_admin", "system_staff", "institute_admin"].includes(role.slug)) ?? false);
async function load() { loading.value = true; error.value = ""; try { const subscriptionRequest = canViewBilling.value ? operationsRepository.subscriptions({ per_page: 100 }) : Promise.resolve({ items: [], page: 1, lastPage: 1, total: 0 }); const [institutePage, memberPage, studentPage, subscriptionPage] = await Promise.all([operationsRepository.institutes({ per_page: 100 }), operationsRepository.members(instituteId(), { per_page: 100 }), operationsRepository.students({ institute_id: instituteId(), per_page: 100 }), subscriptionRequest]); institute.value = institutePage.items.find((item) => item.id === instituteId()) || null; members.value = memberPage.items; students.value = studentPage.items; const studentUsers = new Set(students.value.map((item) => item.userId)); subscriptions.value = subscriptionPage.items.filter((item) => studentUsers.has(item.subscriberId)); } catch (reason) { error.value = reason instanceof Error ? reason.message : "Unable to load institute workspace."; } finally { loading.value = false; } }
watch(() => route.params.instituteId, load); onMounted(load);
</script>

<template><div class="space-y-6"><div><p class="text-[12px] font-semibold uppercase tracking-[0.12em] text-mint">{{ institute?.code || 'Institute' }}</p><h2 class="mt-1 text-[26px] font-bold tracking-[-0.035em]">{{ institute?.name || 'Institute overview' }}</h2><p class="mt-1 text-[13px] text-ink3">Member access, enrolled students and active commercial records.</p></div><p v-if="error" class="rounded-xl bg-pink-light px-4 py-3 text-[13px] text-pink">{{ error }}</p><div class="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><MetricCard label="Students" :value="loading ? '—' : students.length" :icon="GraduationCap" tone="violet" hint="Institute-owned profiles" /><MetricCard label="Members" :value="loading ? '—' : members.length" :icon="Users" hint="Staff and administrators" /><MetricCard label="Subscriptions" :value="loading ? '—' : subscriptions.length" :icon="CreditCard" tone="gold" hint="Student subscriptions" /><MetricCard label="Status" :value="loading ? '—' : institute?.status || 'Unknown'" :icon="Building2" tone="mint" hint="Organisation account" /></div><div class="grid gap-5 xl:grid-cols-2"><DataPanel title="Recent students" description="Latest institute student profiles" :loading="loading" :empty="!students.length"><div class="divide-y divide-border"><div v-for="student in students.slice(0, 6)" :key="student.id" class="flex items-center justify-between gap-3 px-5 py-3.5"><div><p class="text-[12px] font-semibold">{{ student.name }}</p><p class="mt-0.5 text-[11px] text-ink3">{{ student.email }} · {{ student.courseName || 'Course not set' }}</p></div><StatusBadge :value="student.status" /></div></div></DataPanel><DataPanel title="Team members" description="People with institute access" :loading="loading" :empty="!members.length"><div class="divide-y divide-border"><div v-for="member in members.slice(0, 6)" :key="member.id" class="flex items-center justify-between gap-3 px-5 py-3.5"><div><p class="text-[12px] font-semibold">{{ member.name }}</p><p class="mt-0.5 text-[11px] text-ink3">{{ member.email }} · {{ member.position || 'Member' }}</p></div><StatusBadge :value="member.status" /></div></div></DataPanel></div></div></template>
